// Game data lookups built from data/game-data.json (generated by scripts/update-data.mjs).
// Pure module: works in the browser, in workers, and in Node tests.

export const Color = Object.freeze({ Any: 0, Red: 1, Blue: 2, Yellow: 3, Green: 4 });
export const COLOR_NAMES = ["Any", "Red", "Blue", "Yellow", "Green"];
export const RELIC_COLORS = [Color.Red, Color.Blue, Color.Yellow, Color.Green];
export const ItemType = Object.freeze({ Relic: 0, UniqueRelic: 1, DeepRelic: 2, Misc: 3 });
export const EffectType = Object.freeze({ Buff: 0, Debuff: 1 });

/**
 * Turns the raw JSON into fast lookup tables.
 * Effects are interned: one object per effect key, so identity comparison == key comparison.
 */
export function createGameData(json, mmv = null) {
  const effectsByKey = [];
  for (const def of Object.values(json.effects)) effectsByKey[def.key] = Object.freeze({ ...def });
  const knownEffectCount = effectsByKey.length;

  const effectsById = new Map();
  for (const [id, key] of Object.entries(json.effectIdToKey)) effectsById.set(Number(id), effectsByKey[key]);

  // Effects only the More Map Variations mod has (data/mmv-names.json). Their stacking rules
  // aren't known, so they count once per vessel. Keys follow id order so saved builds stay valid.
  const nightfarerIds = new Map(json.nightfarers.map((nf) => [nf.name.toLowerCase(), nf.id]));
  for (const [id, name] of Object.entries(mmv?.effects ?? {}).sort(([a], [b]) => a - b)) {
    if (effectsById.has(Number(id))) continue;
    const nf = nightfarerIds.get(name.match(/^\[(\w+)\]/)?.[1].toLowerCase());
    const def = Object.freeze({ key: effectsByKey.length, slug: `mmv${id}`, name: `${name} (MMV)`, ...(nf !== undefined && { nightfarer: nf }), stacks: false, maxLevel: true, mmv: true });
    effectsByKey.push(def);
    effectsById.set(Number(id), def);
  }
  const mmvItemNames = mmv?.items ?? {};

  const items = new Map();
  for (const [id, item] of Object.entries(json.items)) items.set(Number(id), Object.freeze({ id: Number(id), ...item }));

  const unknownEffects = new Map();
  const unknownItems = new Map();

  /** Save-file effect id -> interned effect. Unknown ids (newer game patch) get a stable placeholder. */
  function effectFromId(id) {
    const known = effectsById.get(id);
    if (known) return known;
    let placeholder = unknownEffects.get(id);
    if (!placeholder) {
      placeholder = Object.freeze({ key: effectsByKey.length, name: `Unknown effect #${id}`, unknown: true, maxLevel: true });
      effectsByKey.push(placeholder);
      unknownEffects.set(id, placeholder);
    }
    return placeholder;
  }

  function item(id) {
    const known = items.get(id);
    if (known) return known;
    let placeholder = unknownItems.get(id);
    if (!placeholder) {
      // Same fallback as upstream: treat unknown relics as red, normal relics
      const name = mmvItemNames[id] ? `${mmvItemNames[id]} (MMV)` : `Unknown relic #${id}`;
      placeholder = Object.freeze({ id, key: `unknown${id}`, name, color: Color.Red, type: ItemType.Relic, unknown: true });
      unknownItems.set(id, placeholder);
    }
    return placeholder;
  }

  const nightfarers = json.nightfarers.map((nf) => Object.freeze({ ...nf, vessels: nf.vessels.map((v) => Object.freeze(v)) }));
  const recommended = {};
  for (const nf of nightfarers) {
    // Upstream expands stackable recommended effects to "this level or better"
    recommended[nf.id] = (json.recommendedEffects[nf.id] ?? []).flatMap((k) => stackableHigherLevel(effectsByKey[k]));
  }

  function stackableHigherLevel(effect) {
    if (effect.level !== undefined && effect.stacks === true) {
      return effectsByKey.filter((e) => e && isSameGroupAndEqualOrBetter(effect, e));
    }
    return [effect];
  }

  return {
    effectsByKey,
    knownEffectCount,
    effectFromId,
    effectByKey: (k) => effectsByKey[k],
    item,
    unknownEffects,
    unknownItems,
    uniqueItemIds: new Set(json.uniqueItemIds),
    unsellableItemIds: new Set(json.unsellableItemIds),
    nightfarers,
    anyoneVessels: json.anyoneVessels,
    recommended,
    stackableHigherLevel,
    source: json.source,
  };
}

export function isSameGroup(a, b) {
  return a.group !== undefined && b.group !== undefined && a.group === b.group;
}

/** True when `b` is in the same group as `a` with an equal or higher level. */
export function isSameGroupAndEqualOrBetter(a, b) {
  return isSameGroup(a, b) && a.level !== undefined && b.level !== undefined && a.level <= b.level;
}

export function relicHasEffect(relic, effect) {
  return relic.effects.some(([e, curse]) => e === effect || curse === effect || isSameGroupAndEqualOrBetter(effect, e));
}

export function relicEffectCount(relic, effect) {
  let n = 0;
  for (const [e, curse] of relic.effects) {
    if (effect === e) n++;
    else if (effect === curse) n++;
    else if (isSameGroupAndEqualOrBetter(effect, e)) n++;
  }
  return n;
}
